type CatalogView = "商店" | "我的";

function PageIntro({ children, note }: { children: React.ReactNode; note: React.ReactNode }) {
  return <div className="mb-4 flex items-end justify-between gap-6"><p className="max-w-[760px] text-[13px] leading-5 text-[#667085]">{children}</p><span className="flex shrink-0 items-center gap-1.5 text-[9.5px] text-[#7A8798]"><ShieldCheck className="size-3.5 text-[#4E70CB]" />{note}</span></div>;
}

function SearchBox({ value, onChange, placeholder }: { value: string; onChange: (value: string) => void; placeholder: string }) {
  return <label className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-[10px] border border-[#DCE3ED] bg-white px-3 focus-within:border-[#9BB6F4] focus-within:ring-2 focus-within:ring-[#DDE7FF]"><Search className="size-3.5 shrink-0 text-[#7B8798]" /><input value={value} onChange={(event) => onChange(event.target.value)} className="min-w-0 flex-1 bg-transparent text-[11px] text-[#344054] outline-none placeholder:text-[#A0A9B7]" placeholder={placeholder} /></label>;
}

function Segments({ value, options, onChange }: { value: string; options: readonly string[]; onChange: (value: string) => void }) {
  return <div className="flex rounded-[10px] bg-[#EAEDF2] p-0.5">{options.map((option) => <button key={option} type="button" onClick={() => onChange(option)} className={`h-8 rounded-lg px-3 text-[10px] transition ${value === option ? "bg-white text-[#344054] shadow-sm" : "text-[#7A8798] hover:text-[#475467]"}`}>{option}</button>)}</div>;
}

function CatalogTabs({ value, onChange, labels }: { value: CatalogView; onChange: (value: CatalogView) => void; labels: { store: string; mine: string } }) {
  return <div className="flex min-w-0 items-end border-b border-[#DDE3EC]">{(["商店", "我的"] as const).map((option) => <button key={option} type="button" onClick={() => onChange(option)} className={`relative h-11 min-w-[108px] px-4 text-left transition ${value === option ? "font-medium text-[#2857C5]" : "text-[#667085] hover:text-[#344054]"}`}><span className="block text-[11.5px]">{option === "商店" ? labels.store : labels.mine}</span><span className="mt-0.5 block text-[8.5px] font-normal text-[#98A2B3]">{option === "商店" ? "发现与获取" : "已拥有与状态"}</span>{value === option ? <span className="absolute inset-x-3 bottom-0 h-0.5 rounded-full bg-[#4269D5]" /> : null}</button>)}</div>;
}

function CatalogList({ title, count, children }: { title: React.ReactNode; count: number; children: React.ReactNode }) {
  return <div className="min-h-0 flex-1 overflow-hidden rounded-2xl border border-[#DDE3EC] bg-white shadow-[0_16px_42px_rgba(28,42,68,.055)]"><div className="flex h-10 items-center justify-between border-b border-[#EEF1F5] bg-[#FAFBFC] px-4 text-[9.5px] text-[#7A8798]"><span className="flex items-center">{title}</span><span className="text-[#98A2B3]">{count} 项</span></div><div className="h-[calc(100%-2.5rem)] overflow-y-auto">{children}</div></div>;
}

function CatalogRow({ icon: Icon, tone, title, description, meta, status, owned, onClick }: { icon: LucideIcon; tone: "blue" | "violet" | "green"; title: string; description: string; meta: React.ReactNode; status: string; owned?: boolean; onClick: () => void }) {
  const iconTone = tone === "violet" ? "bg-[#F0EEFF] text-[#625FD0]" : tone === "green" ? "bg-[#ECF8F2] text-[#268467]" : "bg-[#EEF3FF] text-[#4266C9]";
  const statusTone = status === "已启用" || status === "已安装" || status === "已连接" || status === "已加载" ? "bg-[#ECF8F2] text-[#18845E]" : status.includes("更新") || status.includes("配置") || status.includes("授权") ? "bg-[#FFF4E8] text-[#A56323]" : status.includes("异常") || status.includes("过期") ? "bg-[#FFF1F0] text-[#B24D47]" : "bg-[#F1F3F6] text-[#7A8798]";
  return <button type="button" onClick={onClick} className="group flex w-full items-start gap-3 border-b border-[#EEF1F5] px-5 py-4 text-left transition last:border-b-0 hover:bg-[#F8FAFD]"><span className={`mt-0.5 grid size-9 shrink-0 place-items-center rounded-xl ${iconTone}`}><Icon className="size-[17px]" /></span><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><span className="min-w-0 flex-1 text-[12px] font-medium text-[#253044]">{title}</span>{owned ? <span className="rounded-full border border-[#D9E4F5] bg-white px-2 py-0.5 text-[8.5px] text-[#5B6E91]">已拥有</span> : null}<span className={`rounded-full px-2 py-0.5 text-[8.5px] ${statusTone}`}>{status}</span></span><span className="mt-1.5 line-clamp-2 block text-[10px] leading-4 text-[#667085]">{description}</span><span className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-[8.8px] text-[#98A2B3]">{meta}</span></span><ChevronRight className="mt-3 size-3.5 shrink-0 text-[#C0C7D2] transition group-hover:translate-x-0.5 group-hover:text-[#6D82B6]" /></button>;
}

function DetailPage({ icon: Icon, tone, title, meta, status, onBack, children, actions }: { icon: LucideIcon; tone: "blue" | "violet" | "green"; title: string; meta: string; status: string; onBack: () => void; children: React.ReactNode; actions: React.ReactNode }) {
  const iconTone = tone === "violet" ? "from-[#ECEFFF] to-[#F3EDFF] text-[#615FCC]" : tone === "green" ? "from-[#EAF8F2] to-[#EEF7F7] text-[#288568]" : "from-[#EAF1FF] to-[#EEF4FF] text-[#4568C7]";
  return <div className="min-h-0 flex-1 overflow-y-auto bg-[#F5F7FB]"><div className="mx-auto max-w-[980px] px-7 pb-10 pt-5"><button type="button" onClick={onBack} className="mb-4 flex items-center gap-1.5 rounded-lg px-1 py-1 text-[10px] text-[#667085] hover:text-[#2857C5]"><ArrowLeft className="size-3.5" />返回目录</button><div className="overflow-hidden rounded-2xl border border-[#DDE3EC] bg-white shadow-[0_18px_50px_rgba(28,42,68,.06)]"><div className="flex items-start gap-4 border-b border-[#E9EDF3] bg-[linear-gradient(110deg,#FBFCFF,#F6F8FD)] px-6 py-5"><span className={`grid size-11 shrink-0 place-items-center rounded-[14px] bg-gradient-to-br ${iconTone}`}><Icon className="size-5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-[16px] font-semibold text-[#253044]">{title}</h2><span className="rounded-full bg-[#ECF2FF] px-2.5 py-1 text-[8.8px] text-[#4969BC]">{status}</span></div><p className="mt-1.5 text-[9.5px] text-[#7A8798]">{meta}</p></div><div className="flex shrink-0 items-center gap-2">{actions}</div></div><div className="p-6">{children}</div></div></div></div>;
}

function SectionTitle({ children }: { children: React.ReactNode }) { return <p className="text-[9px] font-semibold uppercase tracking-[0.1em] text-[#98A2B3]">{children}</p>; }
function Notice({ children }: { children: React.ReactNode }) { return <div className="mb-3 flex items-center gap-2 rounded-[10px] border border-[#CFE8DC] bg-[#F1FAF5] px-3 py-2 text-[9.5px] text-[#237253]"><Check className="size-3.5 shrink-0" />{children}</div>; }

