export function AgentsPage({ onUse }: { onUse: (context: TaskContext) => void }) {
  const [view, setView] = useState<CatalogView>("商店");
  const [domain, setDomain] = useState("全部领域");
  const [query, setQuery] = useState("");
  const [agents, setAgents] = useState(agentCatalog);
  const [detailId, setDetailId] = useState<string | null>(null);
  const [notice, setNotice] = useState("");
  const results = useMemo(() => { const keyword = query.trim().toLowerCase(); return agents.filter((item) => (view === "商店" || item.owned) && (domain === "全部领域" || item.domain === domain) && (!keyword || `${item.name}${item.summary}${item.publisher}${item.skills.join("")}`.toLowerCase().includes(keyword))); }, [agents, domain, query, view]);
  const selected = agents.find((item) => item.id === detailId);
  const acquire = (item: AgentItem) => { setAgents((items) => items.map((candidate) => candidate.id === item.id ? { ...candidate, owned: true, enabled: true } : candidate)); setNotice(`“${item.name}”已加载到“我的”，现在可以在普通任务中使用。`); };
  if (selected) {
    const current = agents.find((item) => item.id === selected.id) ?? selected;
    return <DetailPage icon={current.icon ?? Bot} tone="blue" title={current.name} meta={`${current.publisher} · ${current.version} · ${current.stage ?? "共建示例"}`} status={current.owned ? current.enabled ? "已加载" : "未启用" : "商店可获取"} onBack={() => setDetailId(null)} actions={current.owned ? <Button onClick={() => onUse({ id: current.id, kind: "专业智能体", label: current.name })} className="h-9 bg-[#245EDC] px-4 text-[10px] text-white hover:bg-[#1C50C5]">在新任务中使用<ArrowRight className="size-3.5" /></Button> : <Button onClick={() => acquire(current)} className="h-9 bg-[#245EDC] px-4 text-[10px] text-white hover:bg-[#1C50C5]"><Plus className="size-3.5" />获取并加载</Button>}>
      {notice ? <Notice>{notice}</Notice> : null}<p className="rounded-xl bg-[#F5F7FA] p-3 text-[10.5px] leading-5 text-[#475467]">{current.summary}</p><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-xl border border-[#DCE5F4] bg-white p-3"><SectionTitle>适合处理</SectionTitle><ul className="mt-2 space-y-1.5">{current.fit.map((item) => <li key={item} className="flex gap-1.5 text-[9.5px] leading-4 text-[#58667B]"><Check className="mt-0.5 size-3 shrink-0 text-[#258B67]" />{item}</li>)}</ul></div><div className="rounded-xl border border-[#E6E2DA] bg-white p-3"><SectionTitle>不会代替你做</SectionTitle><ul className="mt-2 space-y-1.5">{current.notFit.map((item) => <li key={item} className="flex gap-1.5 text-[9.5px] leading-4 text-[#6D6870]"><span className="mt-[6px] size-1 shrink-0 rounded-full bg-[#C29B72]" />{item}</li>)}</ul></div></div><section className="mt-5 border-t border-[#EBEEF3] pt-4"><SectionTitle>核心判断标准</SectionTitle><div className="mt-2 grid grid-cols-3 gap-2">{current.standards.map((item, index) => <div key={item} className="flex items-start gap-2 rounded-lg bg-[#F7F8FB] px-2.5 py-2 text-[9.5px] leading-4 text-[#58667B]"><span className="mt-0.5 grid size-4 shrink-0 place-items-center rounded-full border border-[#CDD8EF] text-[8px] text-[#5470B8]">{index + 1}</span>{item}</div>)}</div></section><section className="mt-5"><SectionTitle>包含的技能</SectionTitle><div className="mt-2 flex flex-wrap gap-1.5">{current.skills.map((item) => <span key={item} className="rounded-lg border border-[#DCDFF2] bg-[#F9F8FF] px-2 py-1 text-[9px] text-[#5F60A6]">/{item}</span>)}</div></section><section className="mt-5 grid grid-cols-2 gap-4 border-t border-[#EBEEF3] pt-4 text-[9.5px]"><div><SectionTitle>执行依赖</SectionTitle><div className="mt-2 grid grid-cols-2 gap-3"><div><p className="mb-1.5 text-[8.5px] text-[#98A2B3]">连接器</p><div className="space-y-1.5">{current.connectors.length ? current.connectors.map((item) => <div key={item} className="flex items-center gap-1.5 text-[#58667B]"><PlugZap className="size-3 text-[#6078BD]" />{item}</div>) : <span className="text-[#98A2B3]">不依赖具体系统连接</span>}</div></div><div><p className="mb-1.5 text-[8.5px] text-[#98A2B3]">插件</p><div className="space-y-1.5">{current.plugins.map((item) => <div key={item} className="flex items-center gap-1.5 text-[#58667B]"><Boxes className="size-3 text-[#6963C7]" />{item}</div>)}</div></div></div></div><div><SectionTitle>输出与质检</SectionTitle><p className="mt-2 leading-4 text-[#58667B]">{current.outputs.join("、")}</p><p className="mt-1 leading-4 text-[#7A8798]">{current.checks.join("；")}</p></div></section><div className="mt-5 flex gap-2 rounded-xl border border-[#DADFF2] bg-[#F7F7FD] p-3 text-[9.5px] leading-4 text-[#626A86]"><LockKeyhole className="mt-0.5 size-3.5 shrink-0" />加载智能体不会自动读取材料或连接系统；任务运行时仍按实际动作使用最小权限。</div>
    </DetailPage>;
  }
  return <div className="min-h-0 flex-1 overflow-y-auto bg-[#F5F7FB]"><div className="mx-auto flex h-full min-h-[660px] max-w-[1120px] flex-col px-7 pb-7 pt-6"><PageIntro note="能力生态示意 · 非现网成果清单">平台提供通用智能体，各单位可围绕完整业务工作构建、测试并提交；通过统一审核后进入商店供授权用户加载。</PageIntro><CatalogTabs value={view} onChange={(next) => { setView(next); setNotice(""); }} labels={{ store: "智能体商店", mine: "我的智能体" }} /><div className="mb-4 mt-3 flex items-center gap-2"><Segments value={domain} options={["全部领域", "综合办公", "法治监管", "城市治理", "民生服务", "项目建设", "应急环保"]} onChange={setDomain} /><SearchBox value={query} onChange={setQuery} placeholder="搜索专业智能体、适用任务或建议共建单位" /></div>{notice ? <Notice>{notice}</Notice> : null}<CatalogList title={<><Bot className="mr-2 size-3.5 text-[#5472C5]" />{view === "商店" ? "深圳政务专业智能体商店" : "已加载到当前工作空间"}</>} count={results.length}>{results.map((item) => <CatalogRow key={item.id} icon={item.icon ?? Bot} tone="blue" title={item.name} description={item.summary} status={item.owned ? item.enabled ? "已加载" : "未启用" : "可获取"} owned={view === "商店" && item.owned} onClick={() => setDetailId(item.id)} meta={<><span>{item.publisher}</span><span>·</span><span>{item.stage ?? "共建示例"}</span><span>·</span><span>{item.skills.length}个技能</span><span>·</span><span>{item.connectors.length}项可能连接</span></>} />)}</CatalogList></div></div>;
}

