function SkillTabs({ value, onChange }: { value: SkillView; onChange: (value: SkillView) => void }) {
  const items: { value: SkillView; label: string; note: string }[] = [
    { value: "商店", label: "Skill商店", note: "发现与获取" },
    { value: "自建", label: "自建Skill", note: "创建与测试" },
    { value: "我的", label: "我的Skill", note: "已拥有与状态" },
  ];
  return <div className="flex min-w-0 items-end">{items.map((item) => <button key={item.value} type="button" onClick={() => onChange(item.value)} className={`relative h-12 min-w-[118px] px-4 text-left transition ${value === item.value ? "font-medium text-[#2857C5]" : "text-[#667085] hover:text-[#344054]"}`}><span className="block text-[11.5px]">{item.label}</span><span className="mt-0.5 block text-[8.5px] font-normal text-[#98A2B3]">{item.note}</span>{value === item.value ? <span className="absolute inset-x-3 bottom-0 h-0.5 rounded-full bg-[#4269D5]" /> : null}</button>)}</div>;
}

function SkillCard({ item, view, onClick }: { item: SkillItem; view: SkillView; onClick: () => void }) {
  const Icon = item.icon;
  const status = view === "商店" && !item.owned ? "可获取" : item.status;
  const statusTone = status === "已启用" ? "bg-[#EAF8F1] text-[#18845E]" : status.includes("更新") || status.includes("配置") ? "bg-[#FFF4E8] text-[#A56323]" : status === "可获取" ? "bg-[#EEF3FF] text-[#4667BC]" : "bg-[#F1F3F6] text-[#7A8798]";
  return <button type="button" onClick={onClick} className="group flex min-h-[142px] flex-col rounded-[14px] border border-[#E0E5EE] bg-white p-3.5 text-left shadow-[0_8px_24px_rgba(35,50,82,.035)] transition hover:-translate-y-0.5 hover:border-[#BBC9E8] hover:shadow-[0_12px_28px_rgba(44,65,110,.08)]"><span className="flex items-start justify-between gap-2"><span className="grid size-9 place-items-center rounded-[11px] bg-gradient-to-br from-[#ECF1FF] to-[#F1ECFF] text-[#5B63C8]"><Icon className="size-[17px]" /></span><span className="flex items-center gap-1">{item.featured && view === "商店" ? <span className="rounded-full bg-[#F3EEFF] px-1.5 py-0.5 text-[8px] text-[#6B5FBA]">热门</span> : null}<span className={`rounded-full px-1.5 py-0.5 text-[8px] ${statusTone}`}>{status}</span></span></span><span className="mt-3 line-clamp-1 text-[11.5px] font-medium text-[#253044]">{item.name}</span><span className="mt-1.5 line-clamp-2 text-[9.5px] leading-4 text-[#667085]">{item.purpose}</span><span className="mt-auto flex items-center justify-between gap-2 pt-3 text-[8.3px] text-[#98A2B3]"><span className="truncate">{item.source} · {item.domain}</span><ChevronRight className="size-3 shrink-0 transition group-hover:translate-x-0.5 group-hover:text-[#667EBB]" /></span></button>;
}

export function SkillsPage({ onUse }: { onUse: (context: TaskContext) => void }) {
  const [view, setView] = useState<SkillView>("商店"); const [domain, setDomain] = useState("全部领域"); const [query, setQuery] = useState(""); const [skills, setSkills] = useState(skillCatalog); const [detailId, setDetailId] = useState<string | null>(null); const [notice, setNotice] = useState(""); const fileInputRef = useRef<HTMLInputElement>(null);
  const results = useMemo(() => { const keyword = query.trim().toLowerCase(); return skills.filter((item) => (view === "商店" ? item.inStore : view === "自建" ? item.source === "个人" || item.source === "上传" : item.owned) && (domain === "全部领域" || item.domain === domain) && (!keyword || `${item.name}${item.purpose}${item.publisher}${item.source}${item.domain}`.toLowerCase().includes(keyword))); }, [domain, query, skills, view]);
  const selected = skills.find((item) => item.id === detailId);
  const updateSkill = (id: string, change: Partial<SkillItem>, message: string) => { setSkills((items) => items.map((item) => item.id === id ? { ...item, ...change } : item)); setNotice(message); };
  const createWithChat = () => onUse({ id: "create-personal-skill", kind: "Skill", label: "创建个人Skill" });
  const uploadSkill = (file: File) => { const cleanName = file.name.replace(/\.(zip|md|ya?ml|json)$/i, "") || "导入的Skill"; const id = `uploaded-${Date.now()}`; const uploaded: SkillItem = { id, name: cleanName, source: "上传", inStore: false, owned: false, domain: "执行效率", purpose: "从本地Skill包导入，等待完成结构、安全、依赖与低风险测试。", trigger: `/${cleanName}`, publisher: "林思远", version: "待识别", status: "待配置", risk: "尚未完成安全与权限检查", input: "由上传包声明", method: ["校验包结构", "检查依赖与权限声明", "运行低风险测试", "确认后启用并进入我的Skill"], output: "待测试确认", quality: ["未检查前不运行", "依赖必须明确", "权限声明可见"], dependencies: ["待识别"], icon: FileSearch }; setSkills((items) => [uploaded, ...items]); setView("自建"); setDomain("全部领域"); setQuery(""); setDetailId(id); setNotice(`已导入“${file.name}”，完成检查后才会进入“我的Skill”。`); };
  if (selected) {
    const current = skills.find((item) => item.id === selected.id) ?? selected;
    const isImportedDraft = current.source === "上传" && !current.owned;
    const action = isImportedDraft ? <Button onClick={() => updateSkill(current.id, { owned: true, status: "已启用", version: "v0.1" }, `“${current.name}”已通过演示检查，现已进入“我的Skill”。`)} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]"><SearchCheck className="size-3.5" />检查并启用</Button> : !current.owned ? <Button onClick={() => updateSkill(current.id, { owned: true, status: "已启用" }, `“${current.name}”已获取并加载到“我的Skill”。`)} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]"><Plus className="size-3.5" />获取并加载</Button> : current.status === "未启用" || current.status === "待配置" ? <Button onClick={() => updateSkill(current.id, { status: "已启用", version: current.version === "待识别" ? "v0.1" : current.version }, `“${current.name}”已完成演示检查并启用。`)} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]"><Zap className="size-3.5" />{current.status === "待配置" ? "检查并启用" : "启用"}</Button> : current.status === "需要更新" ? <Button onClick={() => updateSkill(current.id, { status: "已启用", version: "v2.0" }, `“${current.name}”已更新并保持启用。`)} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]"><RefreshCw className="size-3.5" />更新并启用</Button> : <Button onClick={() => onUse({ id: current.id, kind: "Skill", label: current.name })} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]">用于新任务<ArrowRight className="size-3.5" /></Button>;
    return <DetailPage icon={current.icon} tone="violet" title={current.name} meta={`${current.publisher} · ${current.version} · ${current.source}`} status={current.owned ? current.status : isImportedDraft ? "自建检查中" : "商店可获取"} onBack={() => setDetailId(null)} actions={action}>{notice ? <Notice>{notice}</Notice> : null}<p className="rounded-xl bg-[#F6F5FC] p-3 text-[10.5px] leading-5 text-[#475467]">{current.purpose}</p><dl className="mt-4 grid grid-cols-[88px_1fr] gap-x-3 gap-y-3 border-y border-[#EBEEF3] py-4 text-[9.8px]"><dt className="text-[#98A2B3]">调用方式</dt><dd className="font-medium text-[#5E60A5]">{current.trigger}</dd><dt className="text-[#98A2B3]">输入要求</dt><dd className="text-[#475467]">{current.input}</dd><dt className="text-[#98A2B3]">预期输出</dt><dd className="text-[#475467]">{current.output}</dd><dt className="text-[#98A2B3]">权限提示</dt><dd className="text-[#475467]">{current.risk}</dd></dl><div className="mt-5 grid grid-cols-2 gap-4"><section><SectionTitle>执行方法</SectionTitle><div className="mt-2 space-y-1.5">{current.method.map((item, index) => <div key={item} className="flex items-center gap-2 rounded-lg bg-[#F7F8FB] px-2.5 py-2 text-[9.5px] text-[#58667B]"><span className="grid size-4 shrink-0 place-items-center rounded-full border border-[#D6D7EA] text-[8px] text-[#6866A8]">{index + 1}</span>{item}</div>)}</div></section><section><SectionTitle>质量要求</SectionTitle><ul className="mt-2 space-y-2 rounded-xl border border-[#E1E4EC] bg-white p-3">{current.quality.map((item) => <li key={item} className="flex gap-1.5 text-[9.5px] leading-4 text-[#58667B]"><Check className="mt-0.5 size-3 shrink-0 text-[#258B67]" />{item}</li>)}</ul><div className="mt-4"><SectionTitle>依赖能力</SectionTitle><div className="mt-2 flex flex-wrap gap-1.5">{current.dependencies.length ? current.dependencies.map((item) => <span key={item} className="rounded-lg border border-[#DCE3F2] bg-white px-2 py-1 text-[9px] text-[#566786]">{item}</span>) : <span className="text-[9.5px] text-[#98A2B3]">无额外依赖</span>}</div></div></section></div>{current.owned && current.status === "已启用" ? <button type="button" onClick={() => updateSkill(current.id, { status: "未启用" }, `“${current.name}”已停用；历史任务记录不受影响。`)} className="mt-5 text-[9.5px] text-[#7A8798] hover:text-[#B24D47]">停用此Skill</button> : null}</DetailPage>;
  }
  const sectionTitle = view === "商店" ? "深圳政务Skill商店" : view === "自建" ? "草稿与自建Skill" : "已拥有的Skill";
  return <div className="min-h-0 flex-1 overflow-y-auto bg-[#F5F7FB]"><input ref={fileInputRef} type="file" accept=".zip,.md,.yaml,.yml,.json" className="hidden" onChange={(event) => { const file = event.target.files?.[0]; if (file) uploadSkill(file); event.target.value = ""; }} /><div className="mx-auto flex min-h-[660px] max-w-[1120px] flex-col px-7 pb-7 pt-5"><PageIntro note="组织审核目录 · 启用不扩大权限">技能既包含业务经验，也包含研究、文档、数据和质量复核等执行方法；底层软件操作仍由插件提供。</PageIntro><div className="flex items-end justify-between gap-4 border-b border-[#DDE3EC]"><SkillTabs value={view} onChange={(next) => { setView(next); setNotice(""); setDomain("全部领域"); }} /><DropdownMenu><DropdownMenuTrigger render={<Button className="mb-1.5 h-8 bg-[#535FC8] px-3 text-[9.5px] text-white hover:bg-[#444FB4]" />}><Plus className="size-3.5" />新建Skill<ChevronDown className="size-3" /></DropdownMenuTrigger><DropdownMenuContent align="end" className="w-56 rounded-xl border border-[#DDE3EC] bg-white p-1.5 shadow-xl"><p className="px-2 py-1.5 text-[9px] font-normal text-[#98A2B3]">进入自建Skill</p><DropdownMenuItem onClick={() => fileInputRef.current?.click()} className="gap-2 rounded-lg px-2.5 py-2 text-[10px]"><FileUp className="size-3.5 text-[#5C6FC0]" /><span><span className="block font-medium text-[#344054]">上传Skill包</span><span className="mt-0.5 block text-[8.5px] text-[#98A2B3]">导入后先检查结构、依赖与权限</span></span></DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem onClick={createWithChat} className="gap-2 rounded-lg px-2.5 py-2 text-[10px]"><Sparkles className="size-3.5 text-[#655FD3]" /><span><span className="block font-medium text-[#344054]">描述需求创建</span><span className="mt-0.5 block text-[8.5px] text-[#98A2B3]">用自然语言沉淀自己的稳定方法</span></span></DropdownMenuItem></DropdownMenuContent></DropdownMenu></div>{view === "自建" ? <div className="mt-3 grid grid-cols-2 gap-2"><button type="button" onClick={createWithChat} className="flex items-center gap-3 rounded-xl border border-[#D7DDF0] bg-[linear-gradient(120deg,#F7F7FF,#F2F5FF)] px-4 py-3 text-left hover:border-[#AEBDE5]"><span className="grid size-9 place-items-center rounded-xl bg-white text-[#5F61C8] shadow-sm"><Sparkles className="size-4" /></span><span><span className="block text-[10.5px] font-medium text-[#344054]">用一句话创建Skill</span><span className="mt-1 block text-[8.8px] text-[#7A8798]">描述经验、样例和质量要求，由智能体协助整理并测试</span></span></button><button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center gap-3 rounded-xl border border-[#DCE3ED] bg-white px-4 py-3 text-left hover:border-[#AEBDE5]"><span className="grid size-9 place-items-center rounded-xl bg-[#F2F5FA] text-[#5F7398]"><FileUp className="size-4" /></span><span><span className="block text-[10.5px] font-medium text-[#344054]">上传已有Skill</span><span className="mt-1 block text-[8.8px] text-[#7A8798]">完成结构、安全、依赖和低风险测试后进入我的Skill</span></span></button></div> : null}<div className="mb-3 mt-3 flex items-center gap-2"><Segments value={domain} options={["全部领域", "政务业务", "研究检索", "文档成果", "数据分析", "执行效率"]} onChange={setDomain} /><SearchBox value={query} onChange={setQuery} placeholder="搜索Skill名称、用途、来源或领域" /></div>{notice ? <Notice>{notice}</Notice> : null}<div className="rounded-2xl border border-[#DDE3EC] bg-[#FAFBFD] shadow-[0_16px_42px_rgba(28,42,68,.045)]"><div className="flex h-10 items-center justify-between border-b border-[#E9EDF3] px-4 text-[9.5px] text-[#6F7C91]"><span className="flex items-center"><Zap className="mr-2 size-3.5 text-[#655FD3]" />{sectionTitle}</span><span className="text-[#98A2B3]">{results.length}项</span></div><div className="grid grid-cols-3 gap-2.5 p-3 xl:grid-cols-4">{results.map((item) => <SkillCard key={item.id} item={item} view={view} onClick={() => setDetailId(item.id)} />)}{results.length === 0 ? <div className="col-span-full py-12 text-center text-[10px] text-[#98A2B3]">没有符合当前条件的Skill</div> : null}</div></div></div></div>;
}

