export function ExtensionsPage({ onUse }: { onUse: (context: TaskContext) => void }) {
  const [section, setSection] = useState<"插件" | "连接器">("插件"); const [view, setView] = useState<CatalogView>("商店"); const [statusFilter, setStatusFilter] = useState("全部状态"); const [query, setQuery] = useState(""); const [plugins, setPlugins] = useState(pluginCatalog); const [connectors, setConnectors] = useState(connectorCatalog); const [detail, setDetail] = useState<{ type: "插件" | "连接器"; id: string } | null>(null); const [notice, setNotice] = useState("");
  const pluginResults = useMemo(() => { const keyword = query.trim().toLowerCase(); return plugins.filter((item) => (view === "商店" || item.owned) && (view === "商店" || statusFilter === "全部状态" || item.status === statusFilter) && (!keyword || `${item.name}${item.purpose}${item.publisher}`.toLowerCase().includes(keyword))); }, [plugins, query, statusFilter, view]);
  const connectorResults = useMemo(() => { const keyword = query.trim().toLowerCase(); return connectors.filter((item) => (view === "商店" || item.owned) && (view === "商店" || statusFilter === "全部状态" || (statusFilter === "待处理" ? item.status !== "已连接" : item.status === statusFilter)) && (!keyword || `${item.name}${item.system}${item.identity}`.toLowerCase().includes(keyword))); }, [connectors, query, statusFilter, view]);
  const selectedPlugin = detail?.type === "插件" ? plugins.find((item) => item.id === detail.id) : undefined; const selectedConnector = detail?.type === "连接器" ? connectors.find((item) => item.id === detail.id) : undefined;
  const updatePlugin = (item: PluginItem) => { const change: Partial<PluginItem> = !item.owned ? { owned: true, status: "已启用" } : item.status === "需要更新" ? { status: "已启用", version: "v2.3" } : item.status === "未启用" || item.status === "依赖待处理" ? { status: "已启用" } : { status: "未启用" }; setPlugins((items) => items.map((candidate) => candidate.id === item.id ? { ...candidate, ...change } : candidate)); setNotice(!item.owned ? `“${item.name}”已安装到“我的插件”；连接器仍需单独授权。` : item.status === "已启用" ? `“${item.name}”已停用；历史任务不受影响。` : `“${item.name}”已更新并启用。`); };
  const connect = (item: ConnectorItem) => { setConnectors((items) => items.map((candidate) => candidate.id === item.id ? { ...candidate, owned: true, status: "已连接", identity: item.owned ? item.identity : "林思远 · 当前政务身份", verified: "刚刚" } : candidate)); setNotice(item.owned ? `“${item.name}”已重新授权；正式业务权限没有扩大。` : `“${item.name}”已添加到“我的连接器”，并使用当前身份完成演示授权。`); };
  if (selectedPlugin) return <DetailPage icon={Boxes} tone="violet" title={selectedPlugin.name} meta={`${selectedPlugin.publisher} · ${selectedPlugin.version}`} status={selectedPlugin.owned ? selectedPlugin.status : "商店可安装"} onBack={() => setDetail(null)} actions={<Button onClick={() => updatePlugin(selectedPlugin)} className="h-9 bg-[#535FC8] px-4 text-[10px] text-white hover:bg-[#444FB4]">{!selectedPlugin.owned ? <><Plus className="size-3.5" />安装插件</> : selectedPlugin.status === "需要更新" ? <><RefreshCw className="size-3.5" />更新插件</> : selectedPlugin.status === "已启用" ? <><Unplug className="size-3.5" />停用插件</> : <><PackageCheck className="size-3.5" />启用插件</>}</Button>}>{notice ? <Notice>{notice}</Notice> : null}<p className="rounded-xl bg-[#F6F5FC] p-3 text-[10.5px] leading-5 text-[#475467]">{selectedPlugin.purpose}</p><section className="mt-5"><SectionTitle>支持的底层能力</SectionTitle><div className="mt-2 grid grid-cols-[92px_1fr] gap-x-3 gap-y-3 rounded-xl border border-[#E3E5EE] p-4 text-[9.8px]"><span className="text-[#98A2B3]">支持动作</span><span className="text-[#58667B]">{(selectedPlugin.capabilities ?? []).join("、")}</span><span className="text-[#98A2B3]">输入输出</span><span className="text-[#58667B]">{(selectedPlugin.formats ?? []).join("、")}</span><span className="text-[#98A2B3]">运行环境</span><span className="text-[#58667B]">{selectedPlugin.runtime ?? "受控运行环境"}</span></div></section><section className="mt-5"><SectionTitle>可能需要的系统连接</SectionTitle><div className="mt-2 flex flex-wrap gap-1.5">{(selectedPlugin.connectors ?? []).length ? (selectedPlugin.connectors ?? []).map((item) => <span key={item} className="rounded-lg border border-[#DCE3F2] bg-white px-2 py-1 text-[9px] text-[#566786]"><PlugZap className="mr-1 inline size-3" />{item}</span>) : <span className="text-[9.5px] text-[#98A2B3]">不依赖具体政务系统连接</span>}</div></section><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-xl bg-[#F7F8FB] p-3"><SectionTitle>能力边界</SectionTitle><p className="mt-2 text-[9.8px] leading-4 text-[#58667B]">{selectedPlugin.access}</p></div><div className="rounded-xl bg-[#F7F8FB] p-3"><SectionTitle>版本说明</SectionTitle><p className="mt-2 text-[9.8px] leading-4 text-[#58667B]">{selectedPlugin.change}</p></div></div><div className="mt-5 flex gap-2 rounded-xl border border-[#E2DCCB] bg-[#FFF9EF] p-3 text-[9.5px] leading-4 text-[#796328]"><LockKeyhole className="mt-0.5 size-3.5 shrink-0" />插件提供底层执行能力；安装插件不会连接具体政务系统、登录账号或批准写入动作。</div></DetailPage>;
  if (selectedConnector) { const connected = selectedConnector.owned && selectedConnector.status === "已连接"; return <DetailPage icon={PlugZap} tone="blue" title={selectedConnector.name} meta={`${selectedConnector.system} · ${selectedConnector.identity}`} status={selectedConnector.owned ? selectedConnector.status : "商店可添加"} onBack={() => setDetail(null)} actions={connected ? <Button onClick={() => onUse({ id: selectedConnector.id, kind: "连接器", label: selectedConnector.name })} className="h-9 bg-[#245EDC] px-4 text-[10px] text-white hover:bg-[#1C50C5]">用于新任务<ArrowRight className="size-3.5" /></Button> : <Button onClick={() => connect(selectedConnector)} className="h-9 bg-[#245EDC] px-4 text-[10px] text-white hover:bg-[#1C50C5]"><Link2 className="size-3.5" />{selectedConnector.owned ? "重新授权" : "添加并连接"}</Button>}>{notice ? <Notice>{notice}</Notice> : null}{selectedConnector.status !== "已连接" ? <div className="mb-4 flex gap-2 rounded-xl border border-[#ECDCB7] bg-[#FFF9EB] p-3 text-[9.5px] leading-4 text-[#87651E]"><CircleAlert className="mt-0.5 size-3.5 shrink-0" />{selectedConnector.approved}</div> : null}<dl className="grid grid-cols-[92px_1fr] gap-x-3 gap-y-3 border-y border-[#EBEEF3] py-4 text-[9.8px]"><dt className="text-[#98A2B3]">当前身份</dt><dd className="text-[#475467]">{selectedConnector.identity}</dd><dt className="text-[#98A2B3]">组织批准</dt><dd className="text-[#475467]">{selectedConnector.approved}</dd><dt className="text-[#98A2B3]">最近核验</dt><dd className="text-[#475467]">{selectedConnector.verified}</dd><dt className="text-[#98A2B3]">最近调用</dt><dd className="text-[#475467]">{selectedConnector.recent}</dd></dl><div className="mt-5 grid grid-cols-2 gap-3"><section className="rounded-xl border border-[#DCE5F4] bg-white p-3"><p className="flex items-center gap-1.5 text-[9px] font-semibold text-[#4F6594]"><Database className="size-3" />允许读取</p><ul className="mt-2 space-y-1.5">{selectedConnector.read.map((item) => <li key={item} className="flex gap-1.5 text-[9.5px] leading-4 text-[#58667B]"><Check className="mt-0.5 size-3 shrink-0 text-[#258B67]" />{item}</li>)}</ul></section><section className="rounded-xl border border-[#E6E2DA] bg-white p-3"><p className="flex items-center gap-1.5 text-[9px] font-semibold text-[#81684E]"><Workflow className="size-3" />可写动作</p>{selectedConnector.write.length ? <ul className="mt-2 space-y-1.5">{selectedConnector.write.map((item) => <li key={item} className="flex gap-1.5 text-[9.5px] leading-4 text-[#6D6870]"><span className="mt-[6px] size-1 shrink-0 rounded-full bg-[#C29B72]" />{item}</li>)}</ul> : <p className="mt-2 text-[9.5px] text-[#98A2B3]">只读连接，不提供写入动作</p>}</section></div><div className="mt-5 rounded-xl border border-[#DADFF2] bg-[#F7F7FD] p-3"><p className="text-[9px] font-semibold text-[#5E6294]">三层门槛</p><div className="mt-2 flex items-center gap-1.5 text-[8.8px] text-[#65708A]"><span className="rounded-md bg-white px-2 py-1">组织允许</span><ArrowRight className="size-3" /><span className="rounded-md bg-white px-2 py-1">身份授权</span><ArrowRight className="size-3" /><span className="rounded-md bg-white px-2 py-1">任务动作确认</span></div></div></DetailPage>; }
  const results = section === "插件" ? pluginResults : connectorResults;
  return <div className="min-h-0 flex-1 overflow-y-auto bg-[#F5F7FB]"><div className="mx-auto flex h-full min-h-[660px] max-w-[1120px] flex-col px-7 pb-7 pt-6"><PageIntro note="组织允许范围 · 插件不等于系统授权">插件提供底层执行能力，连接器连接具体政务系统及当前身份；两者分别安装和授权。</PageIntro><div className="flex items-end justify-between gap-6 border-b border-[#DDE3EC]"><div className="flex items-center gap-4"><Segments value={section} options={["插件", "连接器"]} onChange={(value) => { setSection(value as "插件" | "连接器"); setStatusFilter("全部状态"); setQuery(""); setNotice(""); }} /><CatalogTabs value={view} onChange={(next) => { setView(next); setStatusFilter("全部状态"); setNotice(""); }} labels={{ store: "商店", mine: "我的" }} /></div><span className="mb-3 text-[9px] text-[#98A2B3]">{section === "插件" ? "安装后获得底层能力" : "添加后仍需绑定身份"}</span></div><div className="mb-4 mt-3 flex items-center gap-2"><SearchBox value={query} onChange={setQuery} placeholder={section === "插件" ? "搜索底层能力、适用软件或发布者" : "搜索政务系统、连接器或当前身份"} />{view === "我的" ? <Segments value={statusFilter} options={section === "插件" ? ["全部状态", "已启用", "需要更新"] : ["全部状态", "已连接", "待处理"]} onChange={setStatusFilter} /> : null}</div>{notice ? <Notice>{notice}</Notice> : null}<CatalogList title={section === "插件" ? <><Boxes className="mr-2 size-3.5 text-[#655FD3]" />{view === "商店" ? "深圳政务插件商店" : "我的插件"}</> : <><PlugZap className="mr-2 size-3.5 text-[#5472C5]" />{view === "商店" ? "深圳政务连接器商店" : "我的连接器"}</>} count={results.length}>{section === "插件" ? pluginResults.map((item) => <CatalogRow key={item.id} icon={Boxes} tone="violet" title={item.name} description={item.purpose} status={item.owned ? item.status : "可安装"} owned={view === "商店" && item.owned} onClick={() => setDetail({ type: "插件", id: item.id })} meta={<><span>{item.publisher}</span><span>·</span><span>{item.version}</span><span>·</span><span>{(item.capabilities ?? []).length}项底层能力</span><span>·</span><span>{item.runtime ?? "受控运行环境"}</span></>} />) : connectorResults.map((item) => <CatalogRow key={item.id} icon={PlugZap} tone="blue" title={item.name} description={item.system} status={item.owned ? item.status : "可添加"} owned={view === "商店" && item.owned} onClick={() => setDetail({ type: "连接器", id: item.id })} meta={<><span>{item.identity}</span><span>·</span><span>读取{item.read.length}类</span><span>·</span><span>写入{item.write.length ? `${item.write.length}类` : "无"}</span><span>·</span><span>{item.verified}</span></>} />)}</CatalogList></div></div>;
}
